function time(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(Math.floor(n%60)).padStart(2,'0');}
const status={idle:'集结待命',attack:'灭火作业',rescue:'搜索救援',vent:'排烟通风',stabilize:'楼体加固',return:'正在撤退',refill:'恢复补给',hold:'原地待命'};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function beep(freq=650){if(!soundOn)return;try{audio??=new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.connect(g).connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.04,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.16);o.start();o.stop(audio.currentTime+.17);}catch{}}
function initUI(){let floors='';for(let f=1;f<=game.config.floors;f++){floors+=`<div class="floor-row"><label>${f}F</label>`;for(let c=0;c<3;c++)floors+=`<button class="room" id="room-${(f-1)*3+c}" data-room="${(f-1)*3+c}" aria-label="${f}层${c+1}号房间"></button>`;floors+='</div>';}$('#floors').innerHTML=floors;document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>selectRoom(+b.dataset.room,true));$('#missionName').textContent=game.config.name;$('#missionSub').textContent=game.config.sub;$('#weather').textContent=game.config.weather;$('.operation b').textContent='OP. 00'+(game.level+1);$('#total').textContent=' / '+game.config.people+' 人';renderTeams();updateUI();}
function renderTeams(){$('#teamList').innerHTML=game.units.map(u=>`<button class="team" id="unit-${u.id}" data-unit="${u.id}"><div class="team-top"><span class="unit-icon" style="color:${u.color}">${u.icon}</span><div><div class="unit-name">${u.name}</div><div class="unit-role">${u.role}</div></div><span class="unit-state"></span></div><div class="team-health">O₂ <div class="bar"><i></i></div><b></b><span class="hp"></span></div></button>`).join('');document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{selectedUnit=+b.dataset.unit;updateUI();beep(450);});}
