 for(let r of g.rooms){let b=$('#room-'+r.id);b.className='room'+(r.fire>1?' fire':'')+(r.people>0?' people':'')+(selectedRoom===r.id?' chosen':'');b.innerHTML=(r.fire>1?'♨ '+Math.round(r.fire):'—')+(r.people>0?' <span>⌖'+r.people+'</span>':'');b.title=`${r.floor}F-${r.col+1} · 火势 ${Math.round(r.fire)}% · ${r.people} 人被困`;}
